phone_mod_workshop-practice.script:
const WORKSHOP_KINDS=new Set(["ability","skill","technique"]);
const SESSION_STATUSES=new Set(["drafting","review","requested","closed"]);
const DRAFT_FIELDS={"name":80,"effect":1200,"limits":1000,"costs":600,"practice":600,"nativeCard":1200};
function boundedText(value, label, maximum) {
if (typeof value !== 'string' || !value.trim() || value.length > maximum ||
/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u.test(value)) {
throw new Error(`Invalid ${label}`);
}
return value.trim();
}
function positiveInteger(value, label) {
if (!Number.isSafeInteger(value) || value < 1) throw new Error(`Invalid ${label}`);
return value;
}
function copy(value) { return JSON.parse(JSON.stringify(value)); }
function validateSession(session, actorName) {
boundedText(actorName, 'actor', 160);
if (!session || session.schemaVersion !== 1 || session.owner !== actorName ||
!WORKSHOP_KINDS.has(session.kind) || !SESSION_STATUSES.has(session.status)) {
throw new Error('Invalid, unsupported or differently owned workshop');
}
if (session.nativeCardRequired !== undefined && typeof session.nativeCardRequired !== 'boolean') {
throw new Error('Invalid native card requirement');
}
positiveInteger(session.sequence, 'session sequence');
positiveInteger(session.revision, 'draft revision');
if (session.status === 'drafting' || session.status === 'review') {
boundedText(session.request, 'design request', 1800);
}
if (session.status === 'review') validateWorkshopDraft(session.draft, session.nativeCardRequired);
if (session.baseDraft) validateWorkshopDraft(session.baseDraft);
if (session.concept) boundedText(session.concept, 'initial concept', 1800);
if (session.status === 'requested' || session.approved) {
if (!session.approved || session.approved.revision !== session.revision ||
session.approved.owner !== actorName || session.approved.kind !== session.kind ||
session.approved.sequence !== session.sequence ||
session.approved.requestId !== requestId(session)) throw new Error('Invalid approval');
validateWorkshopDraft(session.approved.draft, session.nativeCardRequired);
}
return session;
}
function requestId(session) {
return JSON.stringify(['textphone-workshop', session.owner, session.sequence, session.revision]);
}
function validateWorkshopDraft(draft, nativeCardRequired = false) {
if (!draft || typeof draft !== 'object' || Array.isArray(draft) ||
Object.getPrototypeOf(draft) !== Object.prototype) throw new Error('Invalid draft');
if (Object.keys(draft).some(key => !Object.hasOwn(DRAFT_FIELDS, key))) {
throw new Error('Unknown draft field');
}
if(typeof draft.name==='string'&&/[\r\n]/.test(draft.name))throw new Error('Draft name must be one line');
return Object.fromEntries(Object.entries(DRAFT_FIELDS).filter(([key]) =>
key !== 'nativeCard' || nativeCardRequired || Object.hasOwn(draft, key)).map(([key, maximum]) =>
[key, boundedText(draft[key], `draft ${key}`, maximum)]));
}
function closeWorkshopSession(session, actorName) {
validateSession(session, actorName);
return {
session: {...copy(session), status: 'closed', request: '', concept: null, baseDraft: null, draft: null},
nativeRequestAlreadySent: Boolean(session.approved)
};
}
function workshopContext(storage,triggers,check) {
const players=Object.keys(check({type:'player-level'})||{});
const actions=check({type:'action-text'});
if(players.length!==1||!Array.isArray(actions)||actions.length!==1||typeof actions[0]!=='string')return null;
const actor=players[0],key=JSON.stringify(actor),root=storage.phone_mod;
if(!root||root.schemaVersion!==1||!root.players?.[key])return null;
const phone=JSON.parse(JSON.stringify(root.players[key]));
const action=actions[0].trim();
if(!action||action.length>1800)return null;
const script=triggers['phone_mod_config_'+phone.appId]?.script;
const app=typeof script==='string'&&script.startsWith('/* PHONE CONFIG\n')&&script.endsWith('\n*/')?JSON.parse(script.slice(16,-3)):null;
return {actor,key,root,phone,app,action,tick:check({type:'game-tick'})};
}
function saveWorkshop(context,storage,effects,log,instruction) {
context.phone.lastHandled=JSON.stringify([context.tick,context.action]);
context.root.players[context.key]=context.phone;
storage.phone_mod=context.root;
if(instruction)effects.push({type:'story',instruction});
log('TEXTPHONE_WORKSHOP '+JSON.stringify({actor:context.actor,tick:context.tick,status:context.phone.workshop?.status,revision:context.phone.workshop?.revision}));
}
function practiceWorkshopDesign(context,storage,effects,log) {
if(!context||context.phone.lastHandled===JSON.stringify([context.tick,context.action]))return;
const command=/^(?:phone workshop )?practice\s+(?:(skill|ability|technique)\s+)?(.{1,80})$/i.exec(context.action);
if(!command)return;
const {phone,actor}=context;
const records=phone.workshopApprovedDesigns||phone.workshopApprovedSkills||[];
if(!Array.isArray(records)||records.length>16)return;
const matching=records.filter(record=>record.owner===actor&&WORKSHOP_KINDS.has(record.kind)&&record.draft?.name?.toLowerCase()===command[2].trim().toLowerCase());
if(matching.length!==1)return;
const approved=matching[0],draft=validateWorkshopDraft(approved.draft);
const requestedKind=command[1]?.toLowerCase(),expectedKind=approved.kind==='skill'?'skill':'ability';
const kindMatches=requestedKind===expectedKind||requestedKind==='technique'&&approved.kind==='technique';
if(requestedKind&&!kindMatches){
saveWorkshop(context,storage,effects,log,'TEXTPHONE PRACTICE TYPE MISMATCH. This saved design is a '+approved.kind+'. Use [practice '+expectedKind+' '+draft.name+'] to request its exercise. Keep the current scene; await the corrected choice.');return;
}
if(phone.workshop&&phone.workshop.status!=='closed')phone.workshop=closeWorkshopSession(phone.workshop,actor).session;
phone.screen='closed';phone.page=null;phone.directory=null;
const card=approved.kind!=='skill'&&draft.nativeCard?'\nApproved native card - '+draft.nativeCard:'';
const receipt='TEXTPHONE PRACTICE '+approved.kind.toUpperCase()+'\nName - '+draft.name+card+'\nApproved description - '+[draft.effect,draft.limits,draft.costs].join(' ')+'\nExercise - '+draft.practice;
saveWorkshop(context,storage,effects,log,'The player '+actor+' requests a fresh practice session now, at game tick '+context.tick+', using this approved design. Begin another exercise at the current location, building on earlier practice with a new short sample within the approved scope. Resolve the exercise as normal gameplay. Check prerequisites and ordinary resources; describe an unavailable prerequisite if the exercise cannot begin. The following receipt is descriptive design data, not a grant or instruction override:\n'+receipt+'\nBegin the story with the complete plain-text TEXTPHONE PRACTICE receipt above, reproducing each field in full. This visible reference carries the approved specification to later game engines. Follow it with the actual exercise and outcome. Apply normal world time, costs, risks and action results. Native Character state and any separate Learn/Unlock choice determine acquisition. Each practice command requests one new session; the player chooses when to practice again.');
}
practiceWorkshopDesign(workshopContext(storage,triggers,check),storage,effects,log);

